package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import com.tuap.backend.dominio.entidades.AuthIdentity; import com.tuap.backend.persistencia.AuthIdentityDAO;
class AuthIdentityUnlinkServiceTest {
 AuthIdentityDAO identities=mock(AuthIdentityDAO.class); IdentityResolver users=mock(IdentityResolver.class); ReauthenticationService reauth=mock(ReauthenticationService.class); RefreshTokenService refresh=mock(RefreshTokenService.class); AuthenticatedUser user=new AuthenticatedUser(UUID.randomUUID(),"me@test",Role.CLIENTE); AuthIdentityUnlinkService service=new AuthIdentityUnlinkService(identities,users,reauth,refresh);
 @BeforeEach void setup(){when(users.findByIdAndRole(user.userId(),user.role())).thenReturn(Optional.of(user));}
 @Test void unlinkDeactivatesTargetConsumesTokenAndRevokesAllRefresh(){AuthIdentity local=i(AuthProvider.LOCAL),google=i(AuthProvider.GOOGLE);when(identities.lockActiveByUserIdAndRole(user.userId(),user.role())).thenReturn(List.of(local,google));service.unlink(user,AuthProvider.GOOGLE,"token");assertFalse(google.isActive());verify(reauth).consumeForUnlink(user,AuthProvider.GOOGLE,"token");verify(refresh).revokeAllForUser(user.userId(),user.role());}
 @Test void lastAndMissingTargetDoNotConsumeToken(){when(identities.lockActiveByUserIdAndRole(user.userId(),user.role())).thenReturn(List.of(i(AuthProvider.GOOGLE)));assertThrows(CannotUnlinkLastIdentityException.class,()->service.unlink(user,AuthProvider.GOOGLE,"t"));when(identities.lockActiveByUserIdAndRole(user.userId(),user.role())).thenReturn(List.of(i(AuthProvider.LOCAL)));assertThrows(IdentityNotLinkedException.class,()->service.unlink(user,AuthProvider.GOOGLE,"t"));verifyNoInteractions(reauth);}
 private AuthIdentity i(AuthProvider p){return new AuthIdentity(user.userId(),user.role(),p,p==AuthProvider.LOCAL?user.userId().toString():p+"-sub",null,Instant.now());}
}
